update pages set contenu = '{"gabarit":"fiche","chapeau":"McCAIN, leader mondial des produits alimentaires à base de pommes de terre, a ouvert à Migen son premier contrat hors de France. Le contrat a démarré en octobre 2024, en Belgique, et il est toujours actif.","fiche":[],"contexte":"**Un équipement critique à l''arrêt ne coûte pas une heure de technicien.** Il coûte des palettes non produites et une qualité produit qui décroche.\nLe besoin exprimé par le site tenait en trois points :\n**Un suivi technique rigoureux** : Une production à grande échelle demande un niveau de maintenance constant, pas une présence de dépannage.\n**La continuité des opérations** : Tenir la production sans interruption non planifiée.\n**La qualité des produits** : Garantir le fonctionnement nominal des machines qui conditionnent la conformité produit.","intervention":"**Renfort des équipes en place** : Plusieurs techniciens Migen ont rejoint les équipes existantes. L''organisation interne reste celle du client.\n**Curatif et préventif dans le même périmètre** : Les techniciens couvrent la maintenance corrective et la maintenance préventive, sans séparer le dépannage de la prévention.\n**Priorité aux équipements critiques** : Les interventions ciblent les machines dont l''arrêt stoppe la chaîne.\n**Prévention ciblée** : Les actions préventives visent les défaillances probables, pour éviter que le correctif n''absorbe le budget.\n**Un régime permanent** : La prestation tourne en continu, sur un engagement à moyen terme.\nLe périmètre technique couvre quatre volets :\nMaintenance des chaînes de production.\nIntervention rapide en cas de dysfonctionnement.\nActions préventives sur les équipements critiques.\nSuivi du fonctionnement nominal des machines.","resultats":[]}'::jsonb where path = '/preuves/mccain-belgique/';
update pages set contenu = jsonb_set(contenu, '{fiche}', (contenu->'fiche') || '[{"libelle":"Client","valeur":"McCAIN"},{"libelle":"Pays","valeur":"Belgique"},{"libelle":"Secteur","valeur":"Agroalimentaire, produits à base de pommes de terre"},{"libelle":"Démarrage","valeur":"Octobre 2024, mission en cours"},{"libelle":"Effectif Migen","valeur":"1 à 3 techniciens"},{"libelle":"Durée","valeur":"Moyen terme"},{"libelle":"Fréquence","valeur":"Permanente"},{"libelle":"Nature des travaux","valeur":"Maintenance corrective et préventive"}]'::jsonb) where path = '/preuves/mccain-belgique/';
update pages set contenu = jsonb_set(contenu, '{resultats}', (contenu->'resultats') || '[{"valeur":"Une sortie du territoire français réussie","libelle":"Le même mode opératoire s''applique, sans structure locale improvisée."},{"valeur":"Une adaptation aux exigences d''un grand groupe","libelle":"Le dispositif tient sur un site de production à grande échelle."},{"valeur":"Une mobilisation rapide d''équipes qualifiées","libelle":"Les profils sont réunis pour un environnement industriel exigeant."}]'::jsonb) where path = '/preuves/mccain-belgique/';
